using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sets the list of commands supported by the bot for the given user scope and language; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetCommandsAsync(BotCommandScope scope = default, string languageCode = default, BotCommand[] commands = default)
    {

           using var activity =  StartCallActivity("SetCommandsAsync", typeof(SetCommands).FullName ?? "SetCommandsAsync");

           try
           {
             return client.SetCommandsAsync(scope, languageCode, commands);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
